/// <summary>
/// To construct METWmsPickingList_OrderPickController class
/// </summary>
/// <returns>new instance of controller</returns>
public static METWmsPickingList_OrderPickController construct()
{
    return new METWmsPickingList_OrderPickController();
}

/// <summary>
/// Main method of METWmsPickingList_OrderPickController class
/// </summary>
/// <param name = "_args">
/// get the menu item name
/// </param>
public static void main(Args _args)
{
    SrsReportRunController formLetterController = METWmsPickingList_OrderPickController::construct();
    METWmsPickingList_OrderPickController controller = formLetterController;
    controller.parmReportName(ssrsReportStr(METWMSPickingList_OrderPick, Report));
    controller.parmArgs(_args);
    controller.initArgs(_args, ssrsReportStr(METWMSPickingList_OrderPick, Report));
    controller.parmDialogCaption(WMSPickingList_OrderPick::reportHeader(_args.parmEnum()));
    controller.startOperation();
}
